// Generates every derived file from tools/data.js and mirrors the hand-written B42 Lua into the B41 tree.
//   npm run gen            -> write files
//   node tools/gen.js --check -> exit 1 if any generated file is out of date (used by npm test)
// B42 (>= 42.15): UTF-8 JSON translations in common/media/lua/shared/Translate/<LANG>/.
// B41: <Type>_<LANG>.txt; EN UTF-8, PTBR Cp1252 (latin1 covers pt-BR).
const fs = require('fs');
const path = require('path');
const D = require('./data');

const MOD = path.join(__dirname, '..', 'Contents', 'mods', 'PassiveSkills');
const B42 = path.join(MOD, '42', 'media');
const B41 = path.join(MOD, 'media');
const COMMON_TR = path.join(MOD, 'common', 'media', 'lua', 'shared', 'Translate');
const CHECK = process.argv.includes('--check');
const outputs = []; // [absPath, Buffer]
const put = (p, data) => outputs.push([p, Buffer.isBuffer(data) ? data : Buffer.from(data, 'utf8')]);

const lstr = (s) => JSON.stringify(s); // safe Lua/PZ string literal for our ASCII+accents text
const header = '-- GENERATED by tools/gen.js from tools/data.js. Do not edit by hand.\n';

// ---------- Catalog.lua (identical in both builds) ----------
const catalog = header +
  'local Catalog = {}\n' +
  `Catalog.TIERS = { ${D.TIERS.map(lstr).join(', ')} }\n` +
  `Catalog.TIER_XP = { ${D.TIER_XP.join(', ')} }\n` +
  `Catalog.TIER_WEIGHTS = { ${D.TIER_WEIGHTS.join(', ')} }\n` +
  'Catalog.SKILLS = {\n' +
  D.SKILLS.map((s) => `    { id = ${lstr(s.id)}, perk = ${lstr(s.perk)}, b41 = ${s.b41} },`).join('\n') + '\n}\n' +
  'Catalog.LEGACY = {\n' +
  D.LEGACY.map((l) => `    { id = ${lstr(l.id)}, aliasOf = ${lstr(l.aliasOf)}, b41 = ${l.b41} },`).join('\n') + '\n}\n' +
  'return Catalog\n';
put(path.join(B42, 'lua', 'shared', 'PassiveSkills', 'Catalog.lua'), catalog);
put(path.join(B41, 'lua', 'shared', 'PassiveSkills', 'Catalog.lua'), catalog);

// ---------- mirror hand-written Lua (B42 is the master copy) ----------
const mirror = [
  ['lua/shared/PassiveSkills/Core.lua', 'lua/shared/PassiveSkills/Core.lua'],
  ['lua/shared/PassiveSkills/Game.lua', 'lua/shared/PassiveSkills/Game.lua'],
  ['lua/shared/PassiveSkills_ReadHook.lua', 'lua/client/PassiveSkills_ReadHook.lua'], // ISReadABook is client-only in B41
  ['lua/client/PassiveSkills_Client.lua', 'lua/client/PassiveSkills_Client.lua'],
  ['lua/server/PassiveSkills_Server.lua', 'lua/server/PassiveSkills_Server.lua'],
];
for (const [from, to] of mirror) put(path.join(B41, to), fs.readFileSync(path.join(B42, from)));

// ---------- items per build ----------
function itemsFor(build) {
  const list = [];
  const skills = D.SKILLS.filter((s) => build >= 42 || s.b41);
  for (const s of skills) D.TIERS.forEach((t, i) => list.push({ id: s.id, tier: i, skill: s, legacy: false }));
  for (const l of D.LEGACY) {
    const target = skills.find((s) => s.id === l.aliasOf);
    if (target && (build >= 42 || l.b41)) D.TIERS.forEach((t, i) => list.push({ id: l.id, tier: i, skill: target, legacy: true }));
  }
  return list;
}
const itemName = (it) => `Magazine${it.id}_${D.TIERS[it.tier]}`;
const skillName = (s, lang, build) => (lang === 'EN' && build < 42 && s.en41) ? s.en41 : (lang === 'EN' ? s.en : s.pt);

function script(build) {
  const items = itemsFor(build);
  let out = '/* GENERATED by tools/gen.js from tools/data.js. Do not edit by hand. */\nmodule Base\n{\n';
  for (const it of items) {
    out += `    item ${itemName(it)}\n    {\n        DisplayCategory = SkillBook,\n`;
    if (build >= 42) out += '        ItemType = base:literature,\n';
    else out += `        Type = Literature,\n        DisplayName = ${D.UI.EN.item(skillName(it.skill, 'EN', build), it.tier + 1)},\n`;
    out += `        Weight = 0.4,\n        Icon = MagazineSkillsPhoto,\n        NumberOfPages = ${D.TIER_PAGES[it.tier]},\n` +
      '        Tooltip = Tooltip_PassiveSkills_Magazine,\n        StaticModel = Magazine,\n        WorldStaticModel = MagazineGround,\n';
    if (build >= 42) out += '        Tags = base:magazine,\n';
    out += '    }\n\n';
  }
  return out.replace(/\n\n$/, '\n') + '}\n';
}
put(path.join(B42, 'scripts', 'PassiveSkills_Magazines.txt'), script(42));
put(path.join(B41, 'scripts', 'PassiveSkills_Magazines.txt'), script(41));

// ---------- sandbox options ----------
const sandbox = `VERSION = 1,

option PassiveSkills.SpawnChance
{
	type = integer,
	min = 0,
	max = 100,
	default = 12,
	page = PassiveSkills,
	translation = PassiveSkills_SpawnChance,
}

option PassiveSkills.XpPercent
{
	type = integer,
	min = 0,
	max = 1000,
	default = 100,
	page = PassiveSkills,
	translation = PassiveSkills_XpPercent,
}
`;
put(path.join(B42, 'sandbox-options.txt'), sandbox);
put(path.join(B41, 'sandbox-options.txt'), sandbox);

// ---------- translations ----------
function tables(lang, build) {
  const u = D.UI[lang];
  const ItemName = {};
  for (const it of itemsFor(build)) ItemName['Base.' + itemName(it)] = u.item(skillName(it.skill, lang, build), it.tier + 1);
  const IGUI = {
    IGUI_PassiveSkills_Learned: u.learned,
    IGUI_PassiveSkills_AlreadyRead: u.already,
    IGUI_PassiveSkills_Halo: u.halo,
  };
  for (const s of D.SKILLS.filter((s) => build >= 42 || s.b41)) IGUI['IGUI_PassiveSkills_Skill_' + s.id] = skillName(s, lang, build);
  const Tooltip = { Tooltip_PassiveSkills_Magazine: u.tooltip };
  const Sandbox = {
    Sandbox_PassiveSkills: u.page,
    Sandbox_PassiveSkills_SpawnChance: u.spawn,
    Sandbox_PassiveSkills_SpawnChance_tooltip: u.spawnTip,
    Sandbox_PassiveSkills_XpPercent: u.xp,
    Sandbox_PassiveSkills_XpPercent_tooltip: u.xpTip,
  };
  return { ItemName, IG_UI: IGUI, Tooltip, Sandbox };
}
const B41_TABLE = { ItemName: 'ItemName', IG_UI: 'IGUI', Tooltip: 'Tooltip', Sandbox: 'Sandbox' };
for (const lang of Object.keys(D.UI)) {
  const t42 = tables(lang, 42);
  for (const [file, obj] of Object.entries(t42)) put(path.join(COMMON_TR, lang, file + '.json'), JSON.stringify(obj, null, 4) + '\n');
  put(path.join(COMMON_TR, lang, 'Mod.json'), JSON.stringify({ name: D.UI[lang].modName, description: D.UI[lang].modDesc }, null, 4) + '\n');
  const t41 = tables(lang, 41);
  for (const [file, obj] of Object.entries(t41)) {
    const prefix = file === 'ItemName' ? 'ItemName_' : '';
    const body = `${B41_TABLE[file]}_${lang} = {\n` +
      Object.entries(obj).map(([k, v]) => `    ${prefix}${k} = ${lstr(v)},`).join('\n') + '\n}\n';
    put(path.join(B41, 'lua', 'shared', 'Translate', lang, `${file}_${lang}.txt`), Buffer.from(body, lang === 'EN' ? 'utf8' : 'latin1'));
  }
}

// ---------- write / check ----------
let stale = 0;
for (const [p, buf] of outputs) {
  const cur = fs.existsSync(p) ? fs.readFileSync(p) : null;
  if (cur && cur.equals(buf)) continue;
  stale++;
  if (CHECK) console.log('stale: ' + path.relative(MOD, p));
  else { fs.mkdirSync(path.dirname(p), { recursive: true }); fs.writeFileSync(p, buf); }
}
if (CHECK) process.exit(stale ? 1 : 0);
console.log(`gen: ${outputs.length} files, ${stale} written`);
